const parseFecha = (v) => {
  if (!v) return null;
  const s = String(v).trim();
  let f = DateTime.fromFormat(s, 'd/M/yyyy H:mm', { zone: 'Atlantic/Canary' });
  if (!f.isValid) f = DateTime.fromFormat(s, 'd/M/yyyy', { zone: 'Atlantic/Canary' });
  if (!f.isValid) f = DateTime.fromISO(s);
  return f.isValid ? f : null;
};

const haceSemana = DateTime.now().minus({ days: 7 });
let total = 0, nuevos = 0, llamadas = 0, citas = 0, inactivos = 0, activos = 0;
for (const item of $input.all()) {
  const r = item.json;
  if (!r.Numero) continue;
  total++;
  const f = parseFecha(r.Fecha) || parseFecha(r.ultima_interaccion);
  if (f && f >= haceSemana) nuevos++;
  const e = String(r.estado || 'nuevo').toLowerCase().replace(/\s+/g, '_');
  if (e === 'llamada_solicitada') llamadas++;
  if (e === 'cita_agendada' || String(r.cita_confirmada || '').toLowerCase() === 'si') citas++;
  if (e === 'inactivo') inactivos++;
  if (e === 'cliente_activo') activos++;
}
const ini = haceSemana.setZone('Atlantic/Canary').toFormat('dd/MM');
const fin = DateTime.now().setZone('Atlantic/Canary').toFormat('dd/MM');
const mensaje = `📊 *Reporte semanal GeorLabs*\n_${ini} — ${fin}_\n\n🆕 Contactos nuevos: ${nuevos}\n📞 Llamadas solicitadas: ${llamadas}\n📅 Citas agendadas: ${citas}\n🤝 Clientes activos: ${activos}\n💤 Inactivos: ${inactivos}\n👥 Total en la base: ${total}\n\n_Generado automáticamente por Geor_ 🤖`;
return [{ json: { mensaje, total, nuevos, llamadas, citas, activos, inactivos } }];

const parseFecha = (v) => {
  if (!v) return null;
  const s = String(v).trim();
  let f = DateTime.fromFormat(s, 'd/M/yyyy H:mm', { zone: 'Atlantic/Canary' });
  if (!f.isValid) f = DateTime.fromFormat(s, 'd/M/yyyy', { zone: 'Atlantic/Canary' });
  if (!f.isValid) f = DateTime.fromISO(s);
  return f.isValid ? f : null;
};

const limite = DateTime.now().minus({ hours: 48 });
const excluir = ['inactivo', 'cita_agendada', 'cerrado', 'cliente_activo', 'perdido', 'llamada_solicitada'];
const inactivos = $input.all().filter(item => {
  const r = item.json;
  const numero = String(r.Numero || '').replace(/\D/g, '');
  if (!/^\d{8,15}$/.test(numero)) return false;
  if (String(r.bot_pausado || '').toLowerCase() === 'si') return false;
  const estado = String(r.estado || 'nuevo').toLowerCase().replace(/\s+/g, '_');
  if (excluir.includes(estado)) return false;
  const f = parseFecha(r.ultima_interaccion) || parseFecha(r.Fecha);
  return f ? f < limite : false;
});
if (inactivos.length === 0) return [{ json: { sinInactivos: true, total: 0 } }];
return inactivos.map(item => ({ json: { ...item.json, sinInactivos: false, numero: String(item.json.Numero).replace(/\D/g, '') } }));

