  if (!f.isValid) f = DateTime.fromISO(s);
  return f.isValid ? f : null;
};
const manana = DateTime.now().setZone('Atlantic/Canary').plus({ days: 1 }).toFormat('dd/MM/yyyy');
const citas = $input.all().map(i => i.json).filter(r => {
  const numero = String(r.Numero || '').replace(/\D/g, '');
  if (!/^\d{8,15}$/.test(numero)) return false;
  const fc = parseFecha(r.fecha_cita);
  if (!fc || fc.toFormat('dd/MM/yyyy') !== manana) return false;
  if (['cerrado', 'perdido'].includes(String(r.estado || '').toLowerCase())) return false;
  if (String(r.recordatorio_enviado || '').toLowerCase() === 'si') return false;
  return true;
});
if (citas.length === 0) return [{ json: { hayCitas: false, total: 0 } }];
return citas.map(r => ({ json: {
  hayCitas: true,
  numero: String(r.Numero).replace(/\D/g, ''),
  nombre: r.Nombre || '',
  fecha_cita: r.fecha_cita,
  hora_cita: r.hora_cita || ''
} }));

