const jidDestino = String($('Webhook').first().json.body.data.key.remoteJid || '');
if (!jidDestino.endsWith('@s.whatsapp.net')) return [];

const raw = $input.first().json.output;
let o = null;
if (raw && typeof raw === 'object') o = raw;
else if (typeof raw === 'string') {
  const s = raw.replace(/```json|```/g, '');
  const i = s.indexOf('{'), j = s.lastIndexOf('}');
  if (i >= 0 && j > i) { try { o = JSON.parse(s.slice(i, j + 1)); } catch (e) {} }
  if (!o && s.trim()) o = { respuesta: s.trim(), intencion: 'otro', solicitar_llamada: false, urgencia: false, resumen_para_equipo: '' };
}
o = o || {};
let respuesta = String(o.respuesta || '').trim()
  || 'Perdona, se me ha liado un poco 😅 ¿Me lo cuentas de otra forma o prefieres que te escriba alguien del equipo?';

// Filtro de seguridad en código: nunca precios ni trozos de las instrucciones
const pareceFuga = /━━━|\bSITUACIONES\b|\bSEGURIDAD\b|RESUMEN PARA EL EQUIPO|FORMATO DE SALIDA|systemMessage/.test(respuesta);
const tienePrecio = /\d[\d.,]*\s*(€|euros?\b|eur\b)|€\s*\d/i.test(respuesta);
const filtrado = pareceFuga || tienePrecio;
if (filtrado) respuesta = 'Los precios y los detalles los prepara el equipo según cada negocio 😊 ¿Te paso el enlace para elegir un hueco y lo veis juntos?';

const remoteJid = $('Webhook').first().json.body.data.key.remoteJid;
const cliente = $('Buscar cliente en Sheets').first().json || {};
const dn = o.datos_cliente || {};
const elegir = (nuevo, viejo) => String(nuevo || '').trim() || String(viejo || '').trim();
const datos = {
  nombre: elegir(dn.nombre, cliente.Nombre),
  negocio: elegir(dn.negocio, cliente.Negocio),
  sector: elegir(dn.sector, cliente.Sector),
  email: elegir(dn.email, cliente.Email)
};
const ahora = DateTime.now().setZone('Atlantic/Canary');
return [{ json: {
  output: respuesta,
  filtrado,
  intencion: o.intencion || 'otro',
  llamadaSolicitada: o.solicitar_llamada === true || o.urgencia === true,
  urgenciaSolicitada: o.urgencia === true,
  resumen: String(o.resumen_para_equipo || '').trim() || 'Sin resumen',
  nombreLlamada: datos.nombre || 'Cliente',
  negocioLlamada: datos.negocio || 'No indicado',
  sectorLlamada: datos.sector || 'No indicado',
  emailLlamada: datos.email || 'No indicado',
  datos,
  remoteJid,
  numero: remoteJid.split('@')[0],
  numeroLimpio: remoteJid.split('@')[0],
  horaContacto: ahora.toFormat('HH:mm'),
  fechaContacto: ahora.toFormat('dd/MM/yyyy')
} }];

const data = $input.first().json;

const botPausado = (data.bot_pausado || '').toLowerCase() === 'si';
const clienteExiste = data.Nombre && 
                      data.Nombre !== '' && 
                      data.Nombre !== 'undefined';

// Si bot pausado → no hacer nada
if (botPausado) {
  return [];
}

return [{
  json: {
