  }
}];

const p = ($input.item.json.body || {}).payload || {};
const nombre = p.name || '';
const email = p.email || '';
let telefono = '';
let negocio = '';
for (const q of (p.questions_and_answers || [])) {
  const pregunta = String(q.question || '').toLowerCase();
  const respuesta = String(q.answer || '');
  if (pregunta.includes('whatsapp') || pregunta.includes('teléfono') || pregunta.includes('telefono')) telefono = respuesta.replace(/\D/g, '');
  if (pregunta.includes('negocio')) negocio = respuesta;
}
if (telefono.startsWith('00')) telefono = telefono.slice(2);
if (telefono.length === 9) telefono = '34' + telefono;
const inicio = (p.scheduled_event && p.scheduled_event.start_time) || (p.event && p.event.start_time) || '';
const dt = inicio ? DateTime.fromISO(inicio).setZone('Atlantic/Canary') : null;
return [{ json: {
  nombre, email, telefono, negocio,
  fecha_cita: dt ? dt.toFormat('dd/MM/yyyy') : '',
  hora_cita: dt ? dt.toFormat('HH:mm') : '',
  fechaCita: dt ? dt.setLocale('es').toFormat("cccc d 'de' LLLL, HH:mm") : 'sin fecha'
} }];

