const data = $input.first().json;
const botPausado = String(data.bot_pausado || '').toLowerCase() === 'si';
if (!botPausado) return [{ json: { ...data, autoReanudado: false } }];
const ultima = parseFecha(data.ultima_interaccion);
const horas = ultima ? DateTime.now().diff(ultima, 'hours').hours : 0;
if (horas >= 2) return [{ json: { ...data, bot_pausado: 'no', autoReanudado: true } }];
return [{ json: { ...data, autoReanudado: false } }];

const body = $json.body;
const text = (body.data.message.conversation || '').trim();
const match = text.match(/^(PAUSAR|REANUDAR)\s*(\d+)?$/i);
const comando = match[1].toUpperCase();
const numeroTexto = match[2] || null;
const miNumero = (body.sender || '').split('@')[0];
const remoteNumero = body.data.key.remoteJid.split('@')[0];
const esSelfChat = remoteNumero === miNumero;

const staticData = $getWorkflowStaticData('global');

if (!numeroTexto && esSelfChat) {
  staticData.pausaGlobal = (comando === 'PAUSAR');
  return [{ json: { ...$json, comando, modo: 'global', numeroObjetivo: null } }];
}

const numeroObjetivo = numeroTexto || remoteNumero;
return [{ json: { ...$json, comando, modo: 'individual', numeroObjetivo } }];

const staticData = $getWorkflowStaticData('global');
if (staticData.pausaGlobal === true) {
  return [];
}
return $input.all();

