const key = ($json.body && $json.body.data && $json.body.data.key) || {};
// Números del equipo: sus chats nunca se pausan (reciben avisos automáticos del propio sistema)
const EQUIPO = ['34600000001', '34600000002'];
const numeroChat = String(key.remoteJid || '').split('@')[0];
const esAutoPausa = !EQUIPO.includes(numeroChat) && key.fromMe === true && typeof key.remoteJid === 'string'
  && !key.remoteJid.includes('@g.us') && !key.remoteJid.includes('@lid') && !key.remoteJid.includes('@broadcast');
return [{ json: { ...$json, esAutoPausa } }];

const miId = $('Webhook').first().json.body.data.key.id;
const loEnvioGeor = $input.all().some(i => i.json.id === miId && i.json.direccion === 'saliente');
if (loEnvioGeor) return [];            // es el eco de un mensaje de GEOR: no pausar
return [{ json: $('Webhook').first().json }];  // lo escribió una persona desde el número: pausar

const body = $('Webhook').first().json.body;
const msg = body.data.message || {};
let texto = '';
try { texto = $('Preparar texto audio').first().json.texto; } catch (e) {}
if (!texto) texto = msg.conversation || (msg.extendedTextMessage || {}).text || '';
return [{ json: { id: body.data.key.id, numero: body.data.key.remoteJid.split('@')[0], texto: String(texto).trim() } }];

const yo = $('Preparar mensaje entrante').first().json;
const filas = $input.all().map(i => i.json).filter(r => r.id)
  .sort((a, b) => (a.row_number || 0) - (b.row_number || 0));
const entrantes = filas.filter(r => r.direccion === 'entrante');
const ultimo = entrantes[entrantes.length - 1];
// Si llegó otro mensaje después del mío, lo contesta la ejecución de ese mensaje
if (ultimo && ultimo.id !== yo.id) return [];
let idxUltimaSalida = -1;
filas.forEach((r, i) => { if (r.direccion === 'saliente') idxUltimaSalida = i; });
const hace30min = Date.now() - 30 * 60 * 1000;
const pendientes = filas.slice(idxUltimaSalida + 1)
  .filter(r => r.direccion === 'entrante' && new Date(r.fecha).getTime() > hace30min)
  .map(r => String(r.texto || '').trim()).filter(Boolean);
const texto = pendientes.length ? pendientes.join('\n') : yo.texto;
const hace24h = Date.now() - 24 * 60 * 60 * 1000;
const intercambios = filas.filter(r => r.direccion === 'saliente' && new Date(r.fecha).getTime() > hace24h).length;
// Conversación reciente (memoria persistente): lo ya respondido de los últimos 7 días
const hace7d = Date.now() - 7 * 24 * 60 * 60 * 1000;
const conversacion = filas.slice(0, idxUltimaSalida + 1)
  .filter(r => new Date(r.fecha).getTime() > hace7d)
  .slice(-12)
  .map(r => (r.direccion === 'saliente' ? 'GEOR: ' : 'Cliente: ') + String(r.texto || '').replace(/\s+/g, ' ').slice(0, 300))
  .join('\n');
return [{ json: { texto, intercambios, mensajesAgrupados: Math.max(pendientes.length, 1), conversacion } }];
